import { DatabaseSync } from 'node:sqlite'
import { existsSync, mkdirSync, readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

// This module is server-only. It must never be imported from client code.
// (It is only ever referenced from `src/utils/products.server.ts`, which is
// exclusively consumed by `createServerFn` handlers.)

type SeedProduct = {
  id: number
  name: string
  description: string
  category: string
  price: number
  inStock: boolean
  rating: number
  createdAt: string
}

const projectRoot = (() => {
  // src/utils -> src -> project root
  const here = dirname(fileURLToPath(import.meta.url))
  return join(here, '..', '..')
})()

const dataDir = join(projectRoot, '.data')
const dbPath = join(dataDir, 'app.db')
const seedPath = join(projectRoot, 'seed', 'products.json')

let db: DatabaseSync | undefined

function createSchema(database: DatabaseSync) {
  database.exec(`
    CREATE TABLE IF NOT EXISTS products (
      id INTEGER PRIMARY KEY,
      name TEXT NOT NULL,
      description TEXT NOT NULL,
      category TEXT NOT NULL,
      price REAL NOT NULL,
      inStock INTEGER NOT NULL,
      rating REAL NOT NULL,
      createdAt TEXT NOT NULL
    );
  `)
}

function seedIfEmpty(database: DatabaseSync) {
  const row = database.prepare('SELECT COUNT(*) as count FROM products').get() as
    | { count: number }
    | undefined

  if (row && row.count > 0) {
    return
  }

  const raw = readFileSync(seedPath, 'utf-8')
  const products = JSON.parse(raw) as Array<SeedProduct>

  const insert = database.prepare(
    `INSERT INTO products (id, name, description, category, price, inStock, rating, createdAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
  )

  database.exec('BEGIN')
  try {
    for (const p of products) {
      insert.run(
        p.id,
        p.name,
        p.description,
        p.category,
        p.price,
        p.inStock ? 1 : 0,
        p.rating,
        p.createdAt,
      )
    }
    database.exec('COMMIT')
  } catch (err) {
    database.exec('ROLLBACK')
    throw err
  }
}

export function getDb(): DatabaseSync {
  if (db) return db

  if (!existsSync(dataDir)) {
    mkdirSync(dataDir, { recursive: true })
  }

  db = new DatabaseSync(dbPath)
  createSchema(db)
  seedIfEmpty(db)

  return db
}

import { z } from 'zod'

export const CATEGORY_VALUES = [
  'electronics',
  'books',
  'clothing',
  'home',
  'toys',
] as const

export type CategorySlug = (typeof CATEGORY_VALUES)[number]

export const SORT_VALUES = [
  'name_asc',
  'price_asc',
  'price_desc',
  'rating_desc',
] as const

export type SortValue = (typeof SORT_VALUES)[number]

export const PAGE_SIZE = 6

export const DEFAULTS = {
  q: '',
  categories: [] as Array<CategorySlug>,
  minPrice: 0,
  maxPrice: 1_000_000,
  inStock: false,
  sort: 'name_asc' as SortValue,
  page: 1,
}

function toNumber(value: unknown): number {
  if (typeof value === 'number') return value
  if (typeof value === 'string' && value.trim() !== '') return Number(value)
  return Number.NaN
}

function toBoolean(value: unknown): boolean {
  if (typeof value === 'boolean') return value
  if (value === 'true' || value === '1') return true
  if (value === 'false' || value === '0') return false
  return false
}

function toStringArray(value: unknown): Array<unknown> {
  if (Array.isArray(value)) return value
  if (typeof value === 'string' && value.length > 0) {
    // Support comma-separated fallback in case the URL was hand-edited.
    return value.split(',')
  }
  return []
}

export const searchParamsSchema = z.object({
  q: z.preprocess(
    (v) => (typeof v === 'string' ? v : DEFAULTS.q),
    z.string(),
  ).catch(DEFAULTS.q),

  categories: z.preprocess(
    (v) => toStringArray(v),
    z.array(z.enum(CATEGORY_VALUES)),
  ).catch(DEFAULTS.categories),

  minPrice: z.preprocess(
    (v) => toNumber(v),
    z.number().finite().min(0),
  ).catch(DEFAULTS.minPrice),

  maxPrice: z.preprocess(
    (v) => toNumber(v),
    z.number().finite().min(0),
  ).catch(DEFAULTS.maxPrice),

  inStock: z.preprocess(
    (v) => toBoolean(v),
    z.boolean(),
  ).catch(DEFAULTS.inStock),

  sort: z.preprocess(
    (v) => (typeof v === 'string' ? v : DEFAULTS.sort),
    z.enum(SORT_VALUES),
  ).catch(DEFAULTS.sort),

  page: z.preprocess(
    (v) => toNumber(v),
    z.number().int().min(1),
  ).catch(DEFAULTS.page),
})

export type ProductSearch = z.infer<typeof searchParamsSchema>
